import React, { useEffect } from 'react'
import { ToastContainer } from 'react-toastify'
import EmplyeesTable from './EmployeesTable'
import useApi from '../../../../hooks/useApi'
import saccosApi from '../../../../api/saccos/saccosApi'
import { useNavigate } from 'react-router-dom'
    const columns = [
        { name: "Title", uid: "title" },
        { name: "Phone", uid: "phone" },
        { name: "Email", uid: "email" },
        { name: "DOB", uid: "dateOfBirth" },
        { name: "Internal Credit Score", uid: "internalCreditScore" },
        { name: "External Credit Score", uid: "externalCreditScore" },
        { name: "Occupation", uid: "occupation" },
        { name: "Date Added", uid: "created" },
        { name: "Actions", uid: "actions" },
    ];

export default function EmployeesList() {
    const [data, setData] = React.useState([])
    const navigate = useNavigate()
  
    const [errors, setErrors] = React.useState([])


    const handleEditAction = (item) => {
        console.log("Edit action for item:", item);
        // Implement your edit action logic here
    }

    const handleAddAction = () => {
        console.log("Add action triggered");
        // Implement your add action logic here
            navigate(`/saccos/members/add-member`)    
    }
    const handleDetailsAction = (item) => {
        console.log("Details action for item:", item);
        // Implement your details action logic here     
    }
    const handleDeleteAction = (item) => {
        console.log("Delete action for item:", item);
        // Implement your delete action logic here  
    }

    const handleFilter = (filter) => {
        console.log("Filter action with filter:", filter);
        // Implement your filter action logic here
    }

    const getEmployeesApi = useApi(saccosApi.saccoStaffAction);

 const getEmployees= async()=>{

        await getEmployeesApi.request({
            action: "GetBranchEmployees",
        });
    }
    useEffect(() => {
        if (getEmployeesApi.data) {
            if (getEmployeesApi.data.length) {
                setData(getEmployeesApi.data);
            }
        }
    }, [getEmployeesApi.data]);

    useEffect(() => {
        getEmployees();
    }, []);




    return (
        <div className="mt-16 md:mt-2">
            <ToastContainer theme="colored" position="bottom-center" />
            <EmplyeesTable
                title={"Branch Staff Members"}
                data={data}
                columns={columns}
                editAction={handleEditAction}
                detailsAction={handleDetailsAction}
                deleteAction={handleDeleteAction}
                addAction={handleAddAction}
                handleFilter={handleFilter}
            />
        </div>

    )
}
